package org.example.admin;

import org.example.member.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Clock;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;

// 13-3 기간 정지 — 끝나는 시각만 저장한다. 풀리는 건 요청마다 "지금 < 끝" 비교로 판단(배치·스케줄러 없음)
@Service
public class SuspensionService {

    private static final String WITHDRAWN = "WITHDRAWN";

    private final SuspensionMapper suspensionMapper;
    private final Clock clock;

    public SuspensionService(SuspensionMapper suspensionMapper, Clock clock) {
        this.suspensionMapper = suspensionMapper;
        this.clock = clock;
    }

    // 이미 정지 중이면 새 기간으로 덮어쓴다(늘리기·줄이기 모두). 운영진(MODERATOR·ADMIN)은 정지할 수 없다 — 409
    @Transactional
    public SuspensionResponse suspend(Long memberId, SuspensionRequest request) {
        MemberSuspensionTarget member = findMember(memberId);
        if (!Role.USER.name().equals(member.role())) {
            throw new ModerationConflictException("운영진은 정지할 수 없습니다. 먼저 역할을 USER로 바꾸세요.");
        }
        LocalDateTime until = LocalDateTime.now(clock).truncatedTo(ChronoUnit.SECONDS).plusDays(request.days());
        suspensionMapper.suspend(memberId, until, request.reason());
        return new SuspensionResponse(member.id(), until, request.reason());
    }

    // 정지가 없어도 204(멱등)
    @Transactional
    public void lift(Long memberId) {
        findMember(memberId);
        suspensionMapper.lift(memberId);
    }

    private MemberSuspensionTarget findMember(Long memberId) {
        MemberSuspensionTarget member = suspensionMapper.findForUpdate(memberId);
        if (member == null || WITHDRAWN.equals(member.memberStatus()) || member.deletedAt() != null) {
            throw new MemberNotFoundException();
        }
        return member;
    }
}

